 "<b style=\"color:#ffd23f;font-size:26px\">Zona radiativa</b><br>la luz rebota durante milenios": "<b style=\"color:#ffd23f;font-size:26px\">Zona radiativa</b><br>la luce rimbalza per millenni",
 "<b style=\"color:#ff9f1c;font-size:26px\">Zona convectiva</b><br>el gas hierve como una olla": "<b style=\"color:#ff9f1c;font-size:26px\">Zona convettiva</b><br>il gas ribolle come in una pentola",
